  mireya_wed_h6: ['mireya', '[distantly] The balcony, señor. Something in the street.'],
  parrot_wed_h7: ['parrot', '¡Rápido! ¡Rápido!'],
  mireya_wed_h7: ['mireya', '[distantly] Follow the wet, señor, before it dries. Only the wet.'],
  parrot_thu_h1: ['parrot', '¡Dos! ¡Dos!'],
  mireya_thu_h1: ['mireya', '[from the kitchen] The señora must find which box is lying, señora. The album of watermarks first.'],
  parrot_thu_h2: ['parrot', '[a flashlight click noise] ¡Click! ¡Click!'],
  mireya_thu_h2: ['mireya', '[from the kitchen] The torch, señora. Low across the page, like the sun at evening.'],
  parrot_thu_h3: ['parrot', '¡Capicúa! ¡Capicúa!'],
  mireya_thu_h3: ['mireya', '[from the kitchen] Go to San Antón, señor. The colmado on the corner. Fello knows everybody.'],
  mireya_thu_h3b: ['mireya', '[from the kitchen] You play dominoes first, señor, then you ask questions. That is San Antón.'],
  parrot_thu_h4: ['parrot', '[nodding its head up and down, silently]'],
  mireya_thu_h4: ['mireya', '[from the kitchen] Tobías does not want to be spoken to, señor. He wants to be understood. You saw what is under St Michael.'],
  parrot_thu_h5: ['parrot', '¡A la catedral! ¡Pelea! ¡Pelea!'],
  mireya_thu_h5: ['mireya', '[from the kitchen] The señora and the doctor come out of the archive at four. The cloister, señor.'],
